import{_ as a}from"./chunks/fs27-0.B96AGPY_.js";import{_ as e,a as l,b as r}from"./chunks/fs38-1.CWH2oeqW.js";import{_ as o,o as s,c as n,a4 as i}from"./chunks/framework.B0hSrcZ6.js";const d="/info/15-ecommerce-s2.webp",h="/info/15-ecommerce-s5.webp",c="/info/15-ecommerce-s6.webp",_=JSON.parse('{"title":"第 15 章 案例：电商与生活实操","description":"精选社区多套实战案例，带你掌握二手闲置上架、图文排版与店铺协同技巧。重点拆解基于 Grok Bot 跨境电商落地方案，展示如何搭建亚马逊运营团队进行前台巡检与买家问答测试，全面赋能日常 AI 电商业务。","frontmatter":{},"headers":[],"relativePath":"part2/15-ecommerce.md","filePath":"part2/15-ecommerce.md","lastUpdated":1792210948000}'),g={name:"part2/15-ecommerce.md"};function p(u,t,b,f,k,m){return s(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="第-15-章-案例-电商与生活实操" tabindex="-1">第 15 章 案例：电商与生活实操 <a class="header-anchor" href="#第-15-章-案例-电商与生活实操" aria-label="Permalink to &quot;第 15 章 案例：电商与生活实操&quot;">​</a></h1><p>单开网页对话框容易丢记录，还得多头切软件搬运。<strong>这章带你用现成方案跑通流程</strong>。</p><ul><li>生活与内容：拿成熟提示词生成闲鱼文案、小红书排版和 SVG 图卡，不再手动对齐。</li><li>跨境电商：从单机巡检起步，搭出 <strong>「1 船长 + 12 岗位」团队</strong>，用待批清单人工把关。</li></ul><h2 id="案例-1-闲鱼上架员-二手闲置资料板与咨询草稿" tabindex="-1">案例 1：闲鱼上架员（二手闲置资料板与咨询草稿） <a class="header-anchor" href="#案例-1-闲鱼上架员-二手闲置资料板与咨询草稿" aria-label="Permalink to &quot;案例 1：闲鱼上架员（二手闲置资料板与咨询草稿）&quot;">​</a></h2><p>Miles Ma（@miles_mazy，灵感源自 @0xlangeai）做了这个 Bot。卖二手直接丢给 AI <strong>容易被瞎编成全新配置</strong>。它把实况与官网参数分流，生成双栏资料板和回复草稿。</p><h3 id="步骤与验收" tabindex="-1">步骤与验收 <a class="header-anchor" href="#步骤与验收" aria-label="Permalink to &quot;步骤与验收&quot;">​</a></h3><ol><li>拍好正面、瑕疵特写和铭牌，理清配件、自提方式与售价。</li><li>在 Grok Bot 侧边栏点 <code>+</code> 选「新建 Bot」，起名「闲鱼上架员」。</li><li>上传实拍图发提示词，以标价 89 元二手罗技 K380s 键盘为例。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一份闲鱼上架资料。商品是罗技 K380s，黑色，用了 8 个月，空格键有轻微磨痕，逐键输入正常，没拆过机；附两节在用电池，无包装，卖 89 元，支持自提，邮费待确认。查官方型号资料，整理标题、商品描述、需要补拍的照片和常见咨询回复，做成可打开的资料板，并附可复制的上架正文。没提供的信息标为待确认。</span></span></code></pre></div><ol start="4"><li>Bot 联网查官网参数，生成 HTML 资料板与纯文本草稿。</li></ol><blockquote><p>来源：<a href="https://x.com/miles_mazy/status/2098708209095819605" target="_blank" rel="noreferrer">Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏</a><br> 作者：<a href="https://x.com/miles_mazy" target="_blank" rel="noreferrer">Miles Ma @miles_mazy</a></p></blockquote><p><img src="'+a+'" alt="Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏" decoding="async"></p><p><img src="'+e+'" alt="Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏" loading="lazy" decoding="async"></p><ul><li>左侧放卖家实况，右侧放标价、成色与配件。</li><li><strong>参数与磨损单列，未提供信息一律标为「待确认」，禁止脑补。</strong></li><li>补图清单列缺漏视角，客服回复覆盖连接、切换与自提。</li><li>案例参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a>。</li></ul><h2 id="案例-2-小红书编辑-从选题到六张知识图卡与画廊" tabindex="-1">案例 2：小红书编辑（从选题到六张知识图卡与画廊） <a class="header-anchor" href="#案例-2-小红书编辑-从选题到六张知识图卡与画廊" aria-label="Permalink to &quot;案例 2：小红书编辑（从选题到六张知识图卡与画廊）&quot;">​</a></h2><p><img src="'+d+'" alt="案例 2：小红书编辑（从选题到六张知识图卡与画廊）" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="制作步骤" tabindex="-1">制作步骤 <a class="header-anchor" href="#制作步骤" aria-label="Permalink to &quot;制作步骤&quot;">​</a></h3><ol><li>在 Grok Bot 侧栏新建 Bot，取名「小红书编辑」。</li><li>敲定选题与知识点，把卡片定为 6 张，设好 1080×1440 尺寸与主辅配色。</li><li>进入对话界面，发送提示词：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给电脑新手做一套小红书图文，主题是“Windows 截图后，图片去哪了”。查微软官方资料，做 6 张 1080×1440 的图：封面、框选截图、整屏保存、当前窗口、剪贴板历史、快捷键对照表。用米白、深蓝和亮黄，文字清楚，配操作示意。直接交 PNG 成图、SVG 源文件和配套发布正文，再做一个能看全套图片的画廊。</span></span></code></pre></div><ol start="4"><li><strong>Bot 会查阅官方文档核对快捷键</strong>，生成 SVG 并渲染 PNG，整合成 HTML 画廊。</li></ol><h3 id="验收与避坑" tabindex="-1">验收与避坑 <a class="header-anchor" href="#验收与避坑" aria-label="Permalink to &quot;验收与避坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">卡片</th><th style="text-align:left;">内容与排版</th></tr></thead><tbody><tr><td style="text-align:left;">第 1 张</td><td style="text-align:left;">封面，大字居中点出截图痛点</td></tr><tr><td style="text-align:left;">第 2-5 张</td><td style="text-align:left;">步骤卡，图解框选、全屏等截图方式</td></tr><tr><td style="text-align:left;">第 6 张</td><td style="text-align:left;">总结卡，4 种截图方式与去向表</td></tr></tbody></table><ul><li>全套卡片采用米白底色配深蓝文字，亮黄点缀。<strong>必须交付 6 张 1080×1440 PNG、SVG 源码、带标签正文与在线画廊</strong>。</li><li>截图自动落盘依赖系统相册设置，<strong>Win + V 查历史必须提前打开开关</strong>，且记录未被覆盖。</li><li>改错别字直接在文本编辑器里改 SVG，<strong>不用重新生图</strong>。</li></ul><p>参考案例：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a></p><h2 id="案例-3-工具情报员-按用途筛选的软件分析简报" tabindex="-1">案例 3：工具情报员（按用途筛选的软件分析简报） <a class="header-anchor" href="#案例-3-工具情报员-按用途筛选的软件分析简报" aria-label="Permalink to &quot;案例 3：工具情报员（按用途筛选的软件分析简报）&quot;">​</a></h2><p>Miles Ma 做的「工具情报员」Bot，专门抓取开源仓库与文档，生成支持分类筛选的网页卡片简报。</p><h3 id="工具限制与推荐任务" tabindex="-1">工具限制与推荐任务 <a class="header-anchor" href="#工具限制与推荐任务" aria-label="Permalink to &quot;工具限制与推荐任务&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">工具</th><th style="text-align:left;">门槛与依赖</th><th style="text-align:left;">主要限制</th><th style="text-align:left;">推荐任务</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>PowerToys</strong></td><td style="text-align:left;">Windows 安装包直接运行</td><td style="text-align:left;">仅限 Windows，部分实验功能偶发不稳定</td><td style="text-align:left;">快捷键提取文字或置顶窗口</td></tr><tr><td style="text-align:left;"><strong>MarkItDown</strong></td><td style="text-align:left;">依赖 Python 或命令行</td><td style="text-align:left;">复杂图文版面识别率有限</td><td style="text-align:left;">批量转 Word 与 PDF 为 Markdown</td></tr><tr><td style="text-align:left;"><strong>changedetection.io</strong></td><td style="text-align:left;">需 Docker 或服务器环境</td><td style="text-align:left;">需运维基础，受反爬限制</td><td style="text-align:left;">监控电商价格标签变动</td></tr></tbody></table><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>在 Grok Bot 侧栏新建 Bot，命名为「工具情报员」。</li><li>确定调研受众与目标工具清单。</li><li>进入对话界面发送提示词。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮内容工作室整理 PowerToys、MarkItDown 和 changedetection.io，查官方仓库和文档。每个工具写清能帮忙做什么、上手需要什么、主要限制，再给一个具体使用例子。做成能按用途筛选的网页简报，附来源链接。</span></span></code></pre></div><ol start="4"><li>Bot 抓取仓库说明与依赖，<strong>编写包含筛选脚本的 HTML 简报</strong>存入工作区。</li></ol><h3 id="验收标准与避坑" tabindex="-1">验收标准与避坑 <a class="header-anchor" href="#验收标准与避坑" aria-label="Permalink to &quot;验收标准与避坑&quot;">​</a></h3><ul><li>每张卡片<strong>包含 6 项核心要素</strong>，覆盖工具定位、上手依赖，以及主要限制、实操任务与官网链接。</li><li>网页顶部设置分类按钮，能平滑筛选卡片。</li><li>限制说明务必客观，明确指出 changedetection.io 需 Docker 或服务器，不夸大为零门槛。</li><li>这属于案头筛选，<strong>Bot 不跑全流程实测</strong>，主要用来快速排除不符合门槛的候选软件。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a></p><h2 id="案例-4-视频教程师-可交互教学工具与带字幕短视频" tabindex="-1">案例 4：视频教程师（可交互教学工具与带字幕短视频） <a class="header-anchor" href="#案例-4-视频教程师-可交互教学工具与带字幕短视频" aria-label="Permalink to &quot;案例 4：视频教程师（可交互教学工具与带字幕短视频）&quot;">​</a></h2><p>这是 Miles Ma（@miles_mazy，灵感源自 @0xlangeai 蓝哥 AI）的玩法。魔方顺逆转动与四次复位很难文字讲清，人工实拍又耗时。<strong>Grok Bot 能在云端写出交互网页，并自动录屏压制字幕</strong>。</p><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ol><li>侧栏新建 Bot，命名为「视频教程师」。</li><li><strong>每次只讲一个基础动作</strong>，避开全套还原算法。</li><li>发送提示词：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给孩子做一个魔方入门小工具，能认识六个面、点按钮演示右面顺转和逆转，再展示右面连续转四次回到原位。把实际操作录成一分钟左右的教学视频，加中文配音和字幕，交付视频和工具文件。</span></span></code></pre></div><ol start="4"><li>Bot 自动写网页、模拟点击并录屏，生成带中文字幕的视频。</li></ol><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">交付项</th><th style="text-align:left;">验收标准</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>交互网页</strong></td><td style="text-align:left;">留存 HTML/JS 源码，点 R 换色，点 R&#39; 复原，复位按钮四次归位，可离线打开</td></tr><tr><td style="text-align:left;"><strong>视频成片</strong></td><td style="text-align:left;">约 51 秒 MP4 与 SRT 字幕，画面动作与字幕对齐</td></tr></tbody></table><p>做后台演示或单点功能教学都能套用这个套路。</p><p>案例参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a>。</p><h2 id="案例-5-收藏整理员-把社媒收藏转化为选题素材库" tabindex="-1">案例 5：收藏整理员（把社媒收藏转化为选题素材库） <a class="header-anchor" href="#案例-5-收藏整理员-把社媒收藏转化为选题素材库" aria-label="Permalink to &quot;案例 5：收藏整理员（把社媒收藏转化为选题素材库）&quot;">​</a></h2><p><img src="'+h+'" alt="案例 5：收藏整理员（把社媒收藏转化为选题素材库）" width="1600" height="1013" loading="lazy" decoding="async"></p><p>Miles Ma（@miles_mazy）做此 Bot，把收藏转成选题库。</p><h3 id="操作步骤-1" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>侧栏新建 Bot，命名「收藏整理员」。</li><li>挑 5 类代表链接（如 115 期播客、图文转换）。</li><li>发送提示词：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理这几条 X 收藏链接，按主题分类，每条留下作者、原链接、核心观点和可以借鉴的写法。再围绕“给新手的 AI 实操教程”提出三个具体选题，做成 Markdown 素材库和选题清单。</span></span></code></pre></div><ol start="4"><li>Bot 整理生成「收藏素材库」与「选题建议」<strong>两份 Markdown 文件</strong>。</li></ol><h3 id="验收与限制" tabindex="-1">验收与限制 <a class="header-anchor" href="#验收与限制" aria-label="Permalink to &quot;验收与限制&quot;">​</a></h3><ul><li>验收：<strong>保留原作者与原链接</strong>，拆解行文逻辑，3 个选题收敛到单次任务可直接做。</li><li>限制：<strong>严禁将他人实操与数据捏造成亲历</strong>，只学结构思路。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a></p><h2 id="案例-6-亚马逊团队搭建-从前台巡检到「1-12」多岗协同" tabindex="-1">案例 6：亚马逊团队搭建（从前台巡检到「1+12」多岗协同） <a class="header-anchor" href="#案例-6-亚马逊团队搭建-从前台巡检到「1-12」多岗协同" aria-label="Permalink to &quot;案例 6：亚马逊团队搭建（从前台巡检到「1+12」多岗协同）&quot;">​</a></h2><p><img src="'+c+`" alt="案例 6：亚马逊团队搭建（从前台巡检到「1+12」多岗协同）" width="1600" height="1013" loading="lazy" decoding="async"></p><h3 id="背景与角色定位" tabindex="-1">背景与角色定位 <a class="header-anchor" href="#背景与角色定位" aria-label="Permalink to &quot;背景与角色定位&quot;">​</a></h3><ul><li><strong>谁</strong>：Zach（@1999Zach22）。</li><li><strong>做了什么</strong>：将原先在本地 Claude/Codex 运行的 Skill 全面迁移至 Grok Bot，在共享云电脑上搭建起「1 个出海船长 + 12 个业务岗位」的亚马逊跨境电商 AI 运营团队。</li></ul><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><p>Codex CLI 这类本地工具得一直开机，出门没法看。<strong>Grok Bot 自带全天候美国云电脑</strong>，手机电脑互通，还能用真实买家账号在亚马逊前台浏览提问。</p><p>Zach 采用 <strong>「1 个船长 + 12 个业务岗位」</strong> 架构。你只对接出海船长，由船长统筹调度各岗位。</p><p><strong>所有岗位严格禁止直接改动店铺后台</strong>，只输出待批清单供人工确认。</p><table tabindex="0"><thead><tr><th style="text-align:left;">岗位</th><th style="text-align:left;">负责什么</th><th style="text-align:left;">严禁触碰的边界</th></tr></thead><tbody><tr><td style="text-align:left;">出海船长</td><td style="text-align:left;">统筹调度下属，汇报周报与清单</td><td style="text-align:left;">不越过人直接做业务决策</td></tr><tr><td style="text-align:left;">助理 / 海盗 / VOC</td><td style="text-align:left;">巡检跟卖、调研选品与分析差评</td><td style="text-align:left;">不登录卖家后台，不擅自立项</td></tr><tr><td style="text-align:left;">财务 / 广告投手</td><td style="text-align:left;">测算单品利润与出具广告建议</td><td style="text-align:left;">绝不登录后台改出价或加否词</td></tr><tr><td style="text-align:left;">文案 / 设计 / 守门员</td><td style="text-align:left;">输出文案、图片与合规终审</td><td style="text-align:left;">不直接发布上线，不替人拍板</td></tr><tr><td style="text-align:left;">复盘机器人</td><td style="text-align:left;">汇总周产出并更新经验库</td><td style="text-align:left;">不粉饰运营问题，不编造业绩</td></tr></tbody></table><h3 id="怎么做-1" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-1" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><h4 id="_1-订阅方案与环境准备" tabindex="-1">1. 订阅方案与环境准备 <a class="header-anchor" href="#_1-订阅方案与环境准备" aria-label="Permalink to &quot;1. 订阅方案与环境准备&quot;">​</a></h4><ul><li><strong>入门选每月 30 美元 Premium 档</strong>（8 美元 Plus 档完全无 Bot），按需升 100 美元 Super 档或 200 美元 Ultra 档。</li><li>电脑手机登录同账号，<strong>确认云电脑正常运行</strong>。详见 <a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">Grok Bot 方案与用量指南</a>。</li></ul><h4 id="_2-先用单-bot-跑通三件事" tabindex="-1">2. 先用单 Bot 跑通三件事 <a class="header-anchor" href="#_2-先用单-bot-跑通三件事" aria-label="Permalink to &quot;2. 先用单 Bot 跑通三件事&quot;">​</a></h4><p>用云电脑美国 IP 与浏览器跑通三项验证：</p><ol><li><strong>自家 Listing 日常巡检</strong>：查主图、价格、变体与跟卖，异常带对比证据汇报。</li><li><strong>测试 Alexa 购物问答</strong>：登录买家号提问，实测约 8 分钟测完 8 类场景、查 30 天历史价格。</li><li><strong>竞品定时盯盘</strong>：记录价格与优惠券，<strong>变动才发通知</strong>，无变动不打扰。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每天固定时间去前台检查自家 Listing：主图和价格是否正确，变体是否正常挂载，核心关键词是否能搜索到，是否存在跟卖。只记录指定商品和关键词，有异常才发提醒，并附带与前一日的对比数据和页面截图证据。不登录店铺后台，不执行任何写操作。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从消费者的角度，尽可能多地把 Alexa for Shopping 体验一遍，最后给我一份报告。</span></span></code></pre></div><h4 id="_3-拆解功能与岗位边界" tabindex="-1">3. 拆解功能与岗位边界 <a class="header-anchor" href="#_3-拆解功能与岗位边界" aria-label="Permalink to &quot;3. 拆解功能与岗位边界&quot;">​</a></h4><ul><li>跑通后将任务拆给 12 个业务岗。</li><li>广告与上新等<strong>敏感岗位明文禁止写入后台</strong>，一律交付「待批清单」，并设清请示边界。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是合理烧钱的广告投手。负责分析广告效率、搜索词转化率、出价与预算建议。</span></span>
<span class="line"><span>边界约束：</span></span>
<span class="line"><span>1. 绝对不登录广告后台，不直接修改出价，不调整预算，不添加否定关键词，不新建广告活动；</span></span>
<span class="line"><span>2. 所有优化建议必须生成「待批清单」，每条建议必须附带调整依据和预期影响；</span></span>
<span class="line"><span>3. 待批清单单线交付给出海船长，由船长提报给业务负责人审核，严禁自主执行。</span></span></code></pre></div><h4 id="_4-编排「1-n」交接链" tabindex="-1">4. 编排「1+N」交接链 <a class="header-anchor" href="#_4-编排「1-n」交接链" aria-label="Permalink to &quot;4. 编排「1+N」交接链&quot;">​</a></h4><ul><li><strong>千万别建多 Bot 群聊</strong>，群聊会重复接收上下文，极速消耗 Token。</li><li><strong>采用 1+N 架构</strong>，人只对接「出海船长」，由船长派活并收拢结果。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是出海船长，负责统筹 12 个业务岗位。日常接收业务负责人的目标，拆解为具体子任务派发给对应岗位。所有下属岗位向你单线汇报，由你汇总结果、审核质量；不达标的打回重做，需要人工决策的整理为带选项和依据的待批清单汇报给人。严格遵守交接链规则：</span></span>
<span class="line"><span>1. 巡检链：助理上报异常与证据，派给数据或广告岗位做归因分析；</span></span>
<span class="line"><span>2. 选品链：海盗提交机会报告，财务测算单品利润，由你整理为立项建议书提报给人；</span></span>
<span class="line"><span>3. 上新链：文案出草稿，设计出图，守门员审核，你做终检后交给人确认，由人工在后台发布；</span></span>
<span class="line"><span>4. 复盘链：收齐各岗位经验，复盘机器人写周报并更新经验库，据此编排下周计划。</span></span>
<span class="line"><span>所有岗位严禁直接登录店铺后台或执行未授权的修改操作。</span></span></code></pre></div><h4 id="_5-资产共用与本地接管" tabindex="-1">5. 资产共用与本地接管 <a class="header-anchor" href="#_5-资产共用与本地接管" aria-label="Permalink to &quot;5. 资产共用与本地接管&quot;">​</a></h4><ul><li><p>所有 Bot <strong>共用同台云电脑与磁盘</strong>，脚本拷入工作区全员可用。</p></li><li><p>读本地文件需在设置「电脑」页<strong>打开「在这台电脑上执行」</strong>（Execution on Local Computer）并交代复制目录。</p><p>细节见 <a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">Grok Bot 计算机和应用文档</a> 与 <a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">Grok Bot 设置说明</a>。</p></li></ul><h3 id="做到什么程度算好-1" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好-1" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/1999Zach22/status/2110078772225667115" target="_blank" rel="noreferrer">用 Grok Bot 做跨境电商的实战分享，从 0 到 1 搭建起一整个亚马逊团队</a><br> 作者：<a href="https://x.com/1999Zach22" target="_blank" rel="noreferrer">Zach @1999Zach22</a></p></blockquote><p><img src="`+l+'" alt="用 Grok Bot 做跨境电商的实战分享，从 0 到 1 搭建起一整个亚马逊团队" loading="lazy" decoding="async"></p><p><img src="'+r+'" alt="用 Grok Bot 做跨境电商的实战分享，从 0 到 1 搭建起一整个亚马逊团队" loading="lazy" decoding="async"></p><ul><li><strong>只跟船长单线对接</strong>，不用切 12 个机器人。</li><li>调价补货走待批清单，<strong>杜绝越权</strong>。</li><li>手机收异常，电脑合盖照常跑巡检。</li></ul><p>案例参考 <a href="https://jcng5q8n0f3z.feishu.cn/wiki/LG1twK03uiO00JkPk1ncQQNUnvt" target="_blank" rel="noreferrer">《用 Grok Bot 做跨境电商的实战分享，从 0 到 1 搭建起一整个亚马逊团队》</a>。</p><h3 id="可以借鉴什么" tabindex="-1">可以借鉴什么 <a class="header-anchor" href="#可以借鉴什么" aria-label="Permalink to &quot;可以借鉴什么&quot;">​</a></h3><ul><li>先用单 Bot <strong>跑顺 SOP</strong> 再拆分。</li><li>走 <strong>「1+N」主从派发</strong>，防群聊把 Token 跑崩。</li><li><strong>只出待批清单</strong>，必须人工后台确认。</li></ul><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ul><li><strong>绝不给卖家后台修改权限</strong>：敏感动作让 Bot 出「待批清单」由人工执行，防错标价格或封店。</li><li><strong>闲鱼防脑补成色</strong>：要求「以卖家提供为准，未提供的标待确认」，防混入官网全新参数致退货。</li><li><strong>别把 12 个 Bot 拉进一个群</strong>：几轮对话就耗光整周额度。改用「1+N」主从架构，靠文件落盘中转。</li><li><strong>竞品抓取以每日 1 次为宜</strong>：几分钟轮询一次极易封 IP 且吃光额度，高频走官方 API 或 MCP。</li><li><strong>认准 30 美元/月的 Premium 档</strong>：8 美元/月的 Plus 没有 Bot 入口；认准 2026-10-12 起的 The X Subscription。</li><li><strong>本地接管必须限路径</strong>：别开始终允许，接管前指定文件路径并保留弹窗确认，防误动私人文件。</li></ul><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><p><strong>交付后对照标准逐项核验</strong>，别大意。</p><ul><li><strong>闲鱼资料板</strong>：瑕疵与官方参数分列，未知项标「待确认」；严禁编自提地址或虚标电池。</li><li><strong>小红书图文</strong>：交 6 张 1080×1440 图卡与 SVG 源码，步骤突出快捷键及系统前提；别弄乱配色。</li><li><strong>工具简报</strong>：单页 HTML 须带筛选与官方链接，据实写明 Docker 环境限制；禁把部署吹成零门槛。</li><li><strong>教学视频</strong>：成片约 1 分钟且音画同步，必须附带网页工具源码；字幕画面别脱节。</li><li><strong>素材库</strong>：留原作者与原帖链接，选题收敛到单次实操；别空泛总结或把他人案例当自己的。</li><li><strong>电商协同</strong>：1+N 架构下只对接船长，调价刊登必出待批清单；严禁私自改价或死循环耗尽用量。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/TV5UwDLTIiTT4vkpY8qcm33fnSf" target="_blank" rel="noreferrer">《Grok Bot 应用指南实操案例：闲鱼上架、小红书做图、找工具、做短视频、整理收藏｜Miles Ma》</a></li><li><a href="https://jcng5q8n0f3z.feishu.cn/wiki/LG1twK03uiO00JkPk1ncQQNUnvt" target="_blank" rel="noreferrer">《用 Grok Bot 做跨境电商的实战分享，从 0 到 1 搭建起一整个亚马逊团队》</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/work" target="_blank" rel="noreferrer">Grok Bot 计算机和应用文档</a></li><li><a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">Grok Bot 方案与用量指南</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">Grok Bot 定时例程配置指南</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">Grok Bot 设置说明</a></li><li><a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">Grok Bot 核心功能使用指南</a></li></ul>',94)])])}const v=o(g,[["render",p]]);export{_ as __pageData,v as default};
